def check_capture(sealed,p,pin,phase,*,runtime_profile='production'):
 need(runtime_profile in ('production','php86-isolated-v1'))
 expected_runtime='8.6.0' if runtime_profile=='php86-isolated-v1' else '8.5.13'

$profile = getenv('PHORGE_PHP_COMPATIBILITY_PROFILE');
if ($profile !== false && $profile !== '') {
  if ($profile !== 'php86-isolated-v1' ||
      getenv('PHORGE_GOVERNANCE_ISOLATED_TEST') !== '1' ||
      !is_string($version) || $version !== PHP_VERSION ||
      !preg_match('/\A8\.6\.[0-9]+\z/', $version)) {
    throw new RuntimeException('Invalid isolated PHP compatibility profile.');
  }
  foreach (array('PHABRICATOR_ENV', 'PHORGE_DEPLOYMENT_CONFIG',
                 'PHORGE_CONTROL_PLANE') as $name) {
    $selected = getenv($name);
    if ($selected !== false && $selected !== '') {
      throw new RuntimeException('Deployment selectors refused by PHP candidate.');
    }
  }
  foreach (array('local.json', 'deployment.json', 'ENVIRONMENT') as $name) {
    $path = dirname(__DIR__, 2).'/conf/local/'.$name;
    if (file_exists($path) || is_link($path)) {
      throw new RuntimeException('Deployment configuration refused by PHP candidate.');
    }
  }
  return;
}

// Do not convert a 128-bit hash through floating-point arithmetic.
// PHP 8.6 reports lossy base conversions; each attempt needs fresh bytes.
$dir = $base.bin2hex(random_bytes(8));
// mkdir is the ownership decision: never adopt/chmod an existing path.
if (@mkdir($dir, $umask)) {
  try {
    if ($umask) { self::changePermissions($dir, $umask); }
  } catch (Throwable $error) {
    @rmdir($dir);
    throw $error;
  }

expected=b'8.6.0' if args.runtime_profile=='php86-isolated-v1' else b'8.5.13'
if version.returncode or version.stdout!=expected:raise ValueError('Exact profile runtime required')
result.update(runtime_profile=args.runtime_profile,runtime=expected.decode())

